def load_data(suffix, exists=True):
    if not exists:
        raise SystemExit('입력 파일이 없습니다')
    if suffix == '.json':
        return 'load_json'
    elif suffix == '.csv':
        return 'load_csv'
    raise SystemExit('지원하지 않는 파일 형식입니다')
print(load_data('.csv'))

